  "code": "async def fetch(u):
    r=await web_fetch({"url":u})
    try:
        d=json.loads(r)
    except Exception: return str(r)
    if isinstance(d,list): d=d[0]
    c=d.get('content')
    if isinstance(c,dict):
        s=c.get('source',{}); return s.get('data','') if isinstance(s,dict) else str(c)
    return str(c) if c else str(d)
for u in ["https://www.cbo.gov/publication/56811","https://www.cbo.gov/publication/58103","https://papers.ssrn.com/sol3/papers.cfm?abstract_id=3232864","https://www.cbo.gov/publication/56898"]:
    c=await fetch(u); pages[u]=c
    i=c.find('main-content',500)
    import re
    print(u,len(c))
    for kw in ['national health expenditure','decrease','increase','trillion','billion','lower','higher']:
        for m in re.finditer(kw,c):
            print('  ..',c[max(0,m.start()-250):m.start()+250].replace('\n',' '))
            break
    print('====')"
